<script lang="ts">
 import {answerHome} from '$lib/home/care.js';
 let {home,role,onchanged,onEquipment}=$props<{home:any,role:string,onchanged:()=>Promise<void>,onEquipment:(id:string)=>void}>();
 let question=$state('');let answers:any[]=$state([]);let action=$state('contact');let title=$state('');let trade=$state('');let phone=$state('');let email=$state('');let description=$state('');let dueAt=$state('');let assignee=$state('');let repeatUnit=$state('');let repeatEvery=$state(1);let taskKind=$state('chore');let scheduleId=$state('');let performedAt=$state('');let message=$state('');let pending:any=$state(null);let saving=$state(false);
 async function save(){pending??={id:crypto.randomUUID(),homeId:home.id,baseRevision:home.revision,kind:action,...(action==='contact'?{value:title,field:trade,phone,email,text:description}:action==='schedule'?{value:title,field:taskKind,dueAt,assignee,text:description,...(repeatUnit?{recurrence:{every:repeatEvery,unit:repeatUnit}}:{})}:{scheduleId,performedAt,text:description,...(home.schedules?.find((s:any)=>s.id===scheduleId)?.recurrence?{occurrenceDueAt:home.schedules.find((s:any)=>s.id===scheduleId).dueAt}:{})})};saving=true;message='';try{const r=await fetch('/api/home/contributions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(pending)});const data=await r.json();if(!r.ok){if(r.status===400)pending=null;throw new Error(data.message??'Save unconfirmed; retry the same entry');}if(data.status==='pending-readback'){message='Confirmation pending; retry this same entry.';}else{pending=null;message='Saved with your account and recording time.';await onchanged();}}catch(e){message=e instanceof Error?e.message:String(e);}finally{saving=false;}}
</script>
<section>
 <h2>Ask your home records</h2><p>Look up a provider or the last recorded service. Missing evidence stays unknown.</p>
 <form onsubmit={e=>{e.preventDefault();answers=answerHome(home,question);}}><label>Your question <input bind:value={question} placeholder="Who is the plumber? When was the furnace last maintained?" required /></label><button>Find answer</button></form>
 {#each answers as answer}<article><p>{answer.text}</p>{#if answer.equipmentId}<button onclick={()=>onEquipment(answer.equipmentId)}>Equipment record</button>{/if}{#each answer.sourceIds??[] as id}<a href={'/api/home/source?id='+encodeURIComponent(id)} target="_blank" rel="noreferrer">Read evidence</a>{/each}</article>{/each}
</section>
<section><h2>People to call</h2>{#if !(home.contacts??[]).length}<p>No providers recorded yet. Add a contact or service invoice.</p>{/if}{#each home.contacts??[] as c}<article><h3>{c.name}</h3><p>{c.trade??'Service provider'}</p><p>{c.phone??''} {c.email??''}</p><p>{c.summary??''}</p><p>Recorded by {c.authorUserId??'not recorded'} · {c.recordedAt??'date unknown'}</p></article>{/each}</section>
<section><h2>Due tasks and chores</h2><p>These are in-app reminders. No messages are sent until a channel and recipients are configured.</p>{#each (home.schedules??[]).filter((s:any)=>['chore','maintenance'].includes(s.kind)) as task}<article><h3>{task.name}</h3><p>{task.state} · Due {task.dueAt??'unknown'} · Assigned to {task.assignee??'not assigned'}</p>{#if task.recurrence}<p>Repeats every {task.recurrence.every} {task.recurrence.unit}. Each occurrence stays due until completion is recorded.</p>{/if}<p>{task.description??''}</p><p>Record {task.contributionId??task.id} · reported by {task.authorUserId??'source record'}</p>{#each task.sources??[] as source}<a href={'/api/home/source?id='+encodeURIComponent(source.id)} target="_blank" rel="noreferrer">Schedule evidence</a>{/each}{#if task.completion}<p>Completed {task.completion.performedAt} · reported by {task.completion.authorUserId??'not recorded'}</p>{/if}</article>{/each}</section>
{#if role!=='viewer'}<section><h2>Add home care information</h2><form onsubmit={e=>{e.preventDefault();save();}}><fieldset disabled={saving||!!pending}><label>Add <select bind:value={action}><option value="contact">Service provider</option><option value="schedule">Due task or chore</option><option value="task-completion">Task completion</option></select></label>
 {#if action==='contact'}<label>Provider name <input bind:value={title} required /></label><label>Trade or service <input bind:value={trade} placeholder="Plumber, electrician, HVAC…" required /></label><label>Phone <input bind:value={phone} /></label><label>Email <input bind:value={email} type="email" /></label>
 {:else if action==='schedule'}<label>Task name <input bind:value={title} required /></label><label>Kind <select bind:value={taskKind}><option value="chore">Chore</option><option value="maintenance">Maintenance</option></select></label><label>Due date <input type="date" bind:value={dueAt} required /></label><label>Repeat <select bind:value={repeatUnit}><option value="">One time</option><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option></select></label>{#if repeatUnit}<label>Repeat every <input type="number" min="1" max="365" step="1" bind:value={repeatEvery} required /></label><p>Choose your interval from your own routine or maintenance guidance. Missed occurrences stay due; they are not automatically skipped.</p>{/if}<label>Assignee (optional) <input bind:value={assignee} /></label>
 {:else}<label>Task <select bind:value={scheduleId} required><option value="">Choose task</option>{#each home.schedules??[] as s}<option value={s.id}>{s.name}</option>{/each}</select></label>{#if home.schedules?.find((s:any)=>s.id===scheduleId)?.recurrence}<p>Completing the occurrence due {home.schedules.find((s:any)=>s.id===scheduleId).dueAt}. The next occurrence advances after this record is accepted.</p>{/if}<label>Actual completion date <input type="date" bind:value={performedAt} required /></label>{/if}
 <label>Notes <textarea bind:value={description} required={action==='task-completion'}></textarea></label></fieldset><button disabled={saving}>{saving?'Saving…':pending?'Retry same entry':'Save care record'}</button></form><p role="status">{message}</p></section>{/if}
<style>section{margin:30px 0}h2{font-size:25px}p{line-height:1.6}form{max-width:620px}label{display:block;margin:15px 0}input,select,textarea{display:block;width:100%;padding:12px;background:white;color:#202c2c;border:1px solid #becfc5;border-radius:8px;margin:8px 0}button{background:white;border:1px solid #cadbd1;border-radius:8px;padding:10px 16px;color:#254a3c;cursor:pointer}fieldset{border:0;padding:0}article{background:white;border:1px solid #dbe4df;padding:20px;border-radius:12px;margin:14px 0}a{color:#216c58;margin-right:15px}</style>
